  1	/* ============================================================
  2	   views/strategy.js — Strategy view (Repository List + Detail/Editor)
  3	   Section 4g of the MCP Server Dashboard SPA
  4	   Depends on: API, Router, escapeHtml, showLoading, showError
  5	   ============================================================ */
  6	
  7	
  8	/* ── renderStrategyList ──────────────────────────────────────
  9	   Renders the repository list at #/strategy.
 10	   Shows: label, folder names, vision status; Add Repository form.
 11	   ─────────────────────────────────────────────────────────── */
 12	function renderStrategyList(app) {
 13	  showLoading(app);
 14	
 15	  API.listRepos().then(function (repos) {
 16	    renderList(repos);
 17	  }).catch(function (err) {
 18	    showError(app, 'Failed to load repositories: ' + (err.message || String(err)));
 19	  });
 20	
 21	  function visionStatus(repo) {
 22	    var vision = repo.vision;
 23	    if (!vision) return '<span class="badge badge-blocked">No vision</span>';
 24	    var hasAny = (vision.short_term && vision.short_term.trim()) ||
 25	                 (vision.mid_term   && vision.mid_term.trim())   ||
 26	                 (vision.long_term  && vision.long_term.trim());
 27	    if (!hasAny) return '<span class="badge badge-blocked">No vision</span>';
 28	    var hasFull = (vision.short_term && vision.short_term.trim()) &&
 29	                  (vision.mid_term   && vision.mid_term.trim())   &&
 30	                  (vision.long_term  && vision.long_term.trim());
 31	    return hasFull
 32	      ? '<span class="badge badge-complete">Full vision</span>'
 33	      : '<span class="badge badge-in-progress">Partial vision</span>';
 34	  }
 35	
 36	  function buildTableHtml(repos) {
 37	    if (!repos.length) {
 38	      return '<p class="text-muted mt-16">No repositories declared yet. Use the form below to add one.</p>';
 39	    }
 40	    var rows = repos.map(function (r) {
 41	      var folderNames = (r.folder_names || []).map(escapeHtml).join(', ') || '<em class="text-muted">—</em>';
 42	      return (
 43	        '<tr>' +
 44	          '<td><a href="#/strategy/' + encodeURIComponent(r.id) + '">' + escapeHtml(r.label || r.id) + '</a></td>' +
 45	          '<td class="text-muted">' + escapeHtml(r.id) + '</td>' +
 46	          '<td>' + folderNames + '</td>' +
 47	          '<td>' + visionStatus(r) + '</td>' +
 48	        '</tr>'
 49	      );
 50	    }).join('');
 51	    return (
 52	      '<table class="data-table">' +
 53	        '<thead><tr>' +
 54	          '<th>Label</th>' +
 55	          '<th>ID</th>' +
 56	          '<th>Folder Names</th>' +
 57	          '<th>Vision</th>' +
 58	        '</tr></thead>' +
 59	        '<tbody>' + rows + '</tbody>' +
 60	      '</table>'
 61	    );
 62	  }
 63	
 64	  function renderList(repos) {
 65	    app.innerHTML =
 66	      '<div class="page-header">' +
 67	        '<h1>Strategy</h1>' +
 68	        '<p class="text-muted">Manage repository declarations and strategic vision.</p>' +
 69	      '</div>' +
 70	      buildTableHtml(repos) +
 71	      '<div class="card mt-24" style="max-width:560px">' +
 72	        '<h2 style="margin-top:0">Add Repository</h2>' +
 73	        '<form id="add-repo-form">' +
 74	          '<div class="form-group">' +
 75	            '<label class="form-label" for="new-repo-id">ID <span class="text-muted">(slug, e.g. my-project)</span></label>' +
 76	            '<input type="text" id="new-repo-id" class="form-control" placeholder="my-project" required>' +
 77	          '</div>' +
 78	          '<div class="form-group">' +
 79	            '<label class="form-label" for="new-repo-label">Label</label>' +
 80	            '<input type="text" id="new-repo-label" class="form-control" placeholder="My Project">' +
 81	          '</div>' +
 82	          '<div class="form-group">' +
 83	            '<label class="form-label" for="new-repo-folders">Folder Names <span class="text-muted">(comma-separated)</span></label>' +
 84	            '<input type="text" id="new-repo-folders" class="form-control" placeholder="my-project, my-project-dev">' +
 85	          '</div>' +
 86	          '<button type="submit" class="btn btn-primary">Add Repository</button>' +
 87	          '<div id="add-repo-msg"></div>' +
 88	        '</form>' +
 89	      '</div>';
 90	
 91	    var form = document.getElementById('add-repo-form');
 92	    if (!form) return;
 93	
 94	    form.addEventListener('submit', function (e) {
 95	      e.preventDefault();
 96	      var msgEl = document.getElementById('add-repo-msg');
 97	      var id = (document.getElementById('new-repo-id').value || '').trim();
 98	      var label = (document.getElementById('new-repo-label').value || '').trim();
 99	      var foldersRaw = (document.getElementById('new-repo-folders').value || '').trim();
100	      var folderNames = foldersRaw

101	        ? foldersRaw.split(',').map(function (f) { return f.trim(); }).filter(Boolean)
102	        : [];
103	
104	      if (!id) {
105	        msgEl.innerHTML = '<p class="error-banner">ID is required.</p>';
106	        return;
107	      }
108	
109	      msgEl.innerHTML = '';
110	      API.createRepo({ id: id, label: label || id, folder_names: folderNames })
111	        .then(function () {
112	          Router.navigate('#/strategy/' + encodeURIComponent(id));
113	        })
114	        .catch(function (err) {
115	          msgEl.innerHTML = '<p class="error-banner">Failed to create repository: ' + escapeHtml(err.message || String(err)) + '</p>';
116	        });
117	    });
118	  }
119	}
