121	/* ── renderStrategyDetail ────────────────────────────────────
122	   Renders the repository detail/editor at #/strategy/:repoId.
123	   Shows: editable label, folder names (add/remove), three-field
124	          vision editor (short-term, mid-term, long-term),
125	          save button, breadcrumb navigation.
126	   ─────────────────────────────────────────────────────────── */
127	function renderStrategyDetail(app, repoId) {
128	  showLoading(app);
129	
130	  API.getRepo(repoId).then(function (repo) {
131	    renderDetail(repo);
132	  }).catch(function (err) {
133	    if (err.code === 'NOT_FOUND' || (err.message && err.message.indexOf('404') !== -1)) {
134	      showError(app, 'Repository not found: ' + escapeHtml(repoId));
135	    } else {
136	      showError(app, 'Failed to load repository: ' + (err.message || String(err)));
137	    }
138	  });
139	
140	  function buildFolderListHtml(folderNames) {
141	    if (!folderNames || !folderNames.length) {
142	      return '<p class="text-muted" id="folder-empty-note">No folder names added yet.</p>';
143	    }
144	    return folderNames.map(function (f, i) {
145	      return (
146	        '<div class="folder-entry" style="display:flex;align-items:center;gap:8px;margin-bottom:6px">' +
147	          '<input type="text" class="form-control folder-name-input" data-folder-idx="' + i + '" value="' + escapeHtml(f) + '" style="flex:1">' +
148	          '<button type="button" class="btn btn-danger btn-sm" data-remove-folder="' + i + '">Remove</button>' +
149	        '</div>'
150	      );

